package com.bank.security;

import java.util.*;
import java.util.logging.*;

public class AuthDemo {
    private static final Logger log = Logger.getLogger(AuthDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthenticationService authn = new AuthenticationService();
        AuthorizationService authz = new AuthorizationService();

        try {
            Principal rajesh = authn.authenticate("rajesh", "secret123");
            log.info(() -> "AUTHN OK: identity established for " + rajesh.getUsername());

            authz.checkCanAccessAccount(rajesh, "SAV2001");
            log.info(() -> "AUTHZ OK: " + rajesh.getUsername() + " may access SAV2001");

            authz.checkCanAccessAccount(rajesh, "CUR3001");
        } catch (AuthorizationException e) {
            log.severe("AUTHZ DENIED (403): " + e.getMessage());
        } catch (AuthenticationException e) {
            log.severe("AUTHN FAILED (401): " + e.getMessage());
        }

        try {
            authn.authenticate("rajesh", "wrongpass");
        } catch (AuthenticationException e) {
            log.severe("AUTHN FAILED (401): " + e.getMessage());
        }
    }
}

