// ─── Would be in AuthenticationService.java ───
class AuthenticationService {
    // In production: look up bcrypt hash from DB and use passwordEncoder.matches().
    private final Map<String, String> passwords = Map.of("rajesh", "secret123", "priya", "secret456");
    private final Map<String, String> roles = Map.of("rajesh", "CUSTOMER", "priya", "CUSTOMER");

    Principal authenticate(String username, String rawPassword) {
        String stored = passwords.get(username);
        if (stored == null || !stored.equals(rawPassword)) {
            throw new AuthenticationException("Invalid username or password");
        }
        return new Principal(username, roles.get(username));
    }
}

// ─── Would be in AuthorizationService.java ───
class AuthorizationService {
    private final Map<String, String> accountOwner = Map.of("SAV2001", "rajesh", "CUR3001", "priya");

    void checkCanAccessAccount(Principal p, String accountId) {
        String owner = accountOwner.get(accountId);
        boolean isOwner = p.getUsername().equals(owner);
        boolean isTeller = "TELLER".equals(p.getRole());
        if (!isOwner && !isTeller) {
            throw new AuthorizationException(
                p.getUsername() + " is not allowed to access account " + accountId);
        }
    }
}

