package com.bank.session;

import java.time.*;
import java.util.*;
import java.util.logging.*;

public class SessionDemo {
    private static final Logger log = Logger.getLogger(SessionDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Server instance A has its own in-memory store.
        SessionStore serverA = new SessionStore();
        SessionAuthService authA = new SessionAuthService(serverA);

        String sessionId = authA.login("rajesh");
        log.info(() -> "Login OK on server A, cookie JSESSIONID=" + sessionId);

        String who = authA.whoAmI(sessionId);
        log.info(() -> "server A resolves session to: " + who);

        // Next request is routed to server B which has a DIFFERENT in-memory store.
        SessionStore serverB = new SessionStore();
        SessionAuthService authB = new SessionAuthService(serverB);
        String whoB = authB.whoAmI(sessionId);
        if (whoB == null) {
            log.severe("server B cannot find session " + sessionId
                + " -> user appears logged out (sticky-session / scalability problem)");
        }
    }
}

// ─── Would be in SessionData.java ───
class SessionData {
    final String username;
    final Instant expiresAt;
    SessionData(String username, Instant expiresAt) {
        this.username = username; this.expiresAt = expiresAt;
    }
    boolean isExpired() { return Instant.now().isAfter(expiresAt); }
}

// ─── Would be in SessionStore.java ───
class SessionStore {
    // In-memory map = state tied to ONE server instance (the core problem).
    private final Map<String, SessionData> store = new HashMap<>();
    void put(String id, SessionData d) { store.put(id, d); }
    SessionData get(String id) { return store.get(id); }
    void remove(String id) { store.remove(id); }   // instant server-side revocation
}

// ─── Would be in SessionAuthService.java ───
class SessionAuthService {
    private final SessionStore store;
    SessionAuthService(SessionStore store) { this.store = store; }

    String login(String username) {
        String sessionId = UUID.randomUUID().toString();
        store.put(sessionId, new SessionData(username, Instant.now().plusSeconds(1800)));
        return sessionId;
    }

    String whoAmI(String sessionId) {
        SessionData d = store.get(sessionId);
        if (d == null || d.isExpired()) return null;
        return d.username;
    }

    void logout(String sessionId) { store.remove(sessionId); }
}

