package com.bank.token;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;
import java.util.logging.*;

public class TokenDemo {
    private static final Logger log = Logger.getLogger(TokenDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String sharedSecret = "national-bank-shared-signing-key-256bit";

        // Auth server issues a token for Rajesh.
        TokenService issuer = new TokenService(sharedSecret);
        String token = issuer.issue("rajesh", "CUSTOMER", 900);
        log.info(() -> "Issued token for rajesh (role=CUSTOMER)");

        // Account Service instance 1 validates it independently.
        TokenService accountSvc = new TokenService(sharedSecret);
        TokenClaims c1 = accountSvc.validate(token);
        log.info(() -> "Account Service #1 validated -> user=" + c1.username + ", role=" + c1.role);

        // A brand-new Settlement Service instance validates the SAME token.
        TokenService settlementSvc = new TokenService(sharedSecret);
        TokenClaims c2 = settlementSvc.validate(token);
        log.info(() -> "Settlement Service (new instance) validated -> user=" + c2.username);

        // Tampered token is rejected.
        try {
            accountSvc.validate(token.substring(0, token.length() - 2) + "xy");
        } catch (InvalidTokenException e) {
            log.severe("Tampered token rejected: " + e.getMessage());
        }

        // Expired token is rejected.
        String expired = issuer.issue("rajesh", "CUSTOMER", -1);
        try {
            accountSvc.validate(expired);
        } catch (InvalidTokenException e) {
            log.severe("Expired token rejected: " + e.getMessage());
        }
    }
}

