    public static void main(String[] args) {
        Subject priya = new Subject("priya", Set.of("TELLER"), "MUMBAI", new BigDecimal("500000"));

        RbacPolicy rbac = new RbacPolicy();
        log.info(() -> "RBAC: priya can approve transfers? " + rbac.canApproveTransfer(priya));
        log.info(() -> "RBAC: priya can close accounts? " + rbac.canCloseAccount(priya));

        AbacPolicy abac = new AbacPolicy(9, 17);
        // In-branch, daytime, under limit -> allowed
        TransferRequest t1 = new TransferRequest("SAV2001", "MUMBAI", new BigDecimal("50000"), 11);
        log.info(() -> "ABAC: in-branch daytime 50k -> " + abac.canApprove(priya, t1));

        // Out-of-branch -> denied
        TransferRequest t2 = new TransferRequest("SAV2001", "DELHI", new BigDecimal("50000"), 11);
        log.warning(() -> "ABAC: out-of-branch -> " + abac.canApprove(priya, t2));

        // After hours -> denied
        TransferRequest t3 = new TransferRequest("SAV2001", "MUMBAI", new BigDecimal("50000"), 20);
        log.warning(() -> "ABAC: after-hours -> " + abac.canApprove(priya, t3));
    }
}

