// ─── Would be in RbacPolicy.java ───
class RbacPolicy {
    boolean canApproveTransfer(Subject s) { return s.hasRole("TELLER") || s.hasRole("ADMIN"); }
    boolean canCloseAccount(Subject s)    { return s.hasRole("ADMIN"); }
}

// ─── Would be in AbacPolicy.java ───
class AbacPolicy {
    private final int startHour, endHour;
    AbacPolicy(int startHour, int endHour) { this.startHour = startHour; this.endHour = endHour; }

    boolean canApprove(Subject s, TransferRequest t) {
        boolean sameBranch = s.branch.equals(t.accountBranch);          // resource attribute
        boolean businessHours = t.hourOfDay >= startHour && t.hourOfDay < endHour; // environment
        boolean underLimit = t.amount.compareTo(s.dailyLimit) <= 0;      // subject attribute
        return s.hasRole("TELLER") && sameBranch && businessHours && underLimit;
    }
}

