package com.bank.jwtval;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Base64;
import java.util.Map;
import java.util.logging.*;

public class JwtValidationDemo {
    private static final Logger log = Logger.getLogger(JwtValidationDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String secret = "national-bank-validation-secret-256bit";
        JwtValidator validator = new JwtValidator(secret, "national-bank", 30);

        long exp = Instant.now().getEpochSecond() + 900;
        String good = mint(secret, "rajesh", "national-bank", exp);
        log.info(() -> "Good token claims: " + validator.validate(good));

        // Tampered payload
        try {
            String[] p = good.split("\\.");
            String evil = Base64.getUrlEncoder().withoutPadding()
                .encodeToString(("rajesh|ADMIN|national-bank|" + exp).getBytes(StandardCharsets.UTF_8));
            validator.validate(p[0] + "." + evil + "." + p[2]);
        } catch (TokenValidationException e) {
            log.severe("Rejected tampered token: " + e.getMessage());
        }

        // Expired
        try {
            validator.validate(mint(secret, "rajesh", "national-bank", Instant.now().getEpochSecond() - 100));
        } catch (TokenValidationException e) {
            log.severe("Rejected expired token: " + e.getMessage());
        }

        // Wrong issuer
        try {
            validator.validate(mint(secret, "rajesh", "fake-bank", exp));
        } catch (TokenValidationException e) {
            log.severe("Rejected wrong-issuer token: " + e.getMessage());
        }

        log.warning("Payload is readable by anyone -> never store PIN/balance/card in it");
    }

    // Helper that mints "sub|role|iss|exp".signature tokens for the demo.
    static String mint(String secret, String sub, String iss, long exp) {
        String payload = sub + "|CUSTOMER|" + iss + "|" + exp;
        String p64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(payload.getBytes(StandardCharsets.UTF_8));
        String h64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString("{\"alg\":\"HS256\"}".getBytes(StandardCharsets.UTF_8));
        return h64 + "." + p64 + "." + JwtValidator.hmac(secret, h64 + "." + p64);
    }
}

// ─── Would be in TokenValidationException.java ───
class TokenValidationException extends RuntimeException {
    TokenValidationException(String m) { super(m); }
}

// ─── Would be in JwtValidator.java ───
class JwtValidator {
    private final String secret;
    private final String expectedIssuer;
    private final long clockSkewSeconds;
    JwtValidator(String secret, String expectedIssuer, long clockSkewSeconds) {
        this.secret = secret; this.expectedIssuer = expectedIssuer; this.clockSkewSeconds = clockSkewSeconds;
    }

    Map<String, String> validate(String token) {
        String[] parts = token.split("\\.");
        if (parts.length != 3) throw new TokenValidationException("malformed token");

        // 1. Signature check (pin our own algorithm; do not trust header alg blindly)
        if (!hmac(secret, parts[0] + "." + parts[1]).equals(parts[2]))
            throw new TokenValidationException("signature invalid (tampered)");

        String payload = new String(Base64.getUrlDecoder().decode(parts[1]), StandardCharsets.UTF_8);
        String[] f = payload.split("\\|"); // sub|role|iss|exp
        String sub = f[0], role = f[1], iss = f[2];
        long exp = Long.parseLong(f[3]);

        // 2. Expiry check (with clock skew)
        if (Instant.now().getEpochSecond() > exp + clockSkewSeconds)
            throw new TokenValidationException("token expired");

        // 3. Issuer check
        if (!expectedIssuer.equals(iss))
            throw new TokenValidationException("untrusted issuer: " + iss);

        return Map.of("sub", sub, "role", role, "iss", iss);
    }

    static String hmac(String secret, String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            return Base64.getUrlEncoder().withoutPadding()
                .encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new TokenValidationException("hmac failed: " + e.getMessage());
        }
    }
}

