class TokenPair {
    final String accessToken;
    final String refreshToken;
    TokenPair(String a, String r) { accessToken = a; refreshToken = r; }
}

// ─── Would be in RefreshRecord.java ───
class RefreshRecord {
    final String familyId;
    final String username;
    boolean used;
    boolean revoked;
    RefreshRecord(String familyId, String username) { this.familyId = familyId; this.username = username; }
}

// ─── Would be in TokenReuseException.java ───
class TokenReuseException extends RuntimeException {
    TokenReuseException(String m) { super(m); }
}

// ─── Would be in AuthServer.java ───
class AuthServer {
    // Map raw refresh token -> record (hash in production).
    private final Map<String, RefreshRecord> store = new HashMap<>();

    TokenPair login(String username) {
        String familyId = UUID.randomUUID().toString();
        return issuePair(username, familyId);
    }

    TokenPair refresh(String refreshToken) {
        RefreshRecord rec = store.get(refreshToken);
        if (rec == null) throw new TokenReuseException("unknown refresh token");
        if (rec.revoked) throw new TokenReuseException("refresh token revoked (family locked)");
        if (rec.used) {
            // A used token presented again = theft. Revoke the entire family.
            revokeFamily(rec.familyId);
            throw new TokenReuseException("refresh token already used (reuse detected)");
        }
        rec.used = true;                       // burn the old token (rotation)
        return issuePair(rec.username, rec.familyId);
    }

    private TokenPair issuePair(String username, String familyId) {
        String access = "acc-" + UUID.randomUUID();           // short-lived JWT in production
        String refresh = "ref-" + UUID.randomUUID();          // long-lived, server-tracked
        store.put(refresh, new RefreshRecord(familyId, username));
        return new TokenPair(access, refresh);
    }

    private void revokeFamily(String familyId) {
        for (RefreshRecord r : store.values())
            if (r.familyId.equals(familyId)) r.revoked = true;
    }
}

