        ClientBackend backend = new ClientBackend("partner-site", "super-secret", authServer);

        // Front channel: user consents, server returns a CODE to the browser (not a token).
        String code = authServer.issueCode("rajesh", "https://partner.example/callback");
        log.info(() -> "Front-channel redirect carried only a CODE: " + code);

