class OpenIdProvider {
    private final String issuer;
    private final Map<String, String[]> identities = Map.of(
        "rajesh-001", new String[]{"Rajesh Kumar", "rajesh@example.com"});
    OpenIdProvider(String issuer) { this.issuer = issuer; }

    // Returns a (simulated, already-decoded) signed ID token as claims.
    Map<String, String> issueIdToken(String sub, String audience, String nonce) {
        String[] who = identities.get(sub);
        Map<String, String> claims = new HashMap<>();
        claims.put("iss", issuer);
        claims.put("sub", sub);
        claims.put("aud", audience);
        claims.put("nonce", nonce);
        claims.put("name", who[0]);
        claims.put("email", who[1]);
        claims.put("sig", "valid"); // signature verified against JWKS in production
        return claims;
    }
}

