class RelyingParty {
    private final String clientId;
    private final String expectedIssuer;
    RelyingParty(String clientId, String expectedIssuer) {
        this.clientId = clientId; this.expectedIssuer = expectedIssuer;
    }

    Map<String, String> login(Map<String, String> idToken, String expectedNonce) {
        if (!"valid".equals(idToken.get("sig")))
            throw new IdTokenValidationException("bad signature");
        if (!expectedIssuer.equals(idToken.get("iss")))
            throw new IdTokenValidationException("untrusted issuer");
        if (!clientId.equals(idToken.get("aud")))
            throw new IdTokenValidationException("audience mismatch: " + idToken.get("aud"));
        if (!expectedNonce.equals(idToken.get("nonce")))
            throw new IdTokenValidationException("nonce mismatch (possible replay)");
        return Map.of("sub", idToken.get("sub"), "name", idToken.get("name"),
                      "email", idToken.get("email"));
    }
}

