        perms.grant("reporting-service", "account:read"); // minimum needed

        // Read-only service can READ.
        perms.checkPermission("reporting-service", "account:read");
        log.info("reporting-service read allowed (has account:read)");

        // Same service CANNOT write — deny by default, no privilege creep.
        try {
            perms.checkPermission("reporting-service", "account:write");
        } catch (AccessDeniedException e) {
            log.severe("reporting-service write blocked: " + e.getMessage());
        }

        // Admin gets JUST-IN-TIME, TIME-BOUNDED elevation to unlock an account.
        perms.elevate("admin-priya", "account:unlock", Duration.ofMinutes(10));
        perms.checkPermission("admin-priya", "account:unlock");
        log.info("admin-priya temporarily elevated -> unlock allowed");

        // After expiry, the elevated permission is gone again.
        perms.expireNow("admin-priya", "account:unlock"); // simulate time passing
        try {
            perms.checkPermission("admin-priya", "account:unlock");
        } catch (AccessDeniedException e) {
            log.warning("admin-priya elevation expired: " + e.getMessage());
        }
    }
