class Grant {
    final String permission;
    final Instant expiresAt; // null = permanent
    Grant(String permission, Instant expiresAt) { this.permission = permission; this.expiresAt = expiresAt; }
    boolean valid() { return expiresAt == null || Instant.now().isBefore(expiresAt); }
}

// ─── Would be in AccessDeniedException.java ───
class AccessDeniedException extends RuntimeException {
    AccessDeniedException(String m) { super(m); }
}

// ─── Would be in PermissionService.java ───
class PermissionService {
    private final Map<String, List<Grant>> grants = new HashMap<>();

    void grant(String principal, String permission) {
        grants.computeIfAbsent(principal, k -> new ArrayList<>()).add(new Grant(permission, null));
    }
    void elevate(String principal, String permission, Duration ttl) {
        grants.computeIfAbsent(principal, k -> new ArrayList<>())
              .add(new Grant(permission, Instant.now().plus(ttl)));
    }
    void expireNow(String principal, String permission) {
        List<Grant> list = grants.getOrDefault(principal, List.of());
        list.removeIf(g -> g.permission.equals(permission)); // simulate expiry
    }
    // Deny by default: allowed ONLY if a valid grant exists.
    void checkPermission(String principal, String permission) {
        boolean allowed = grants.getOrDefault(principal, List.of()).stream()
            .anyMatch(g -> g.permission.equals(permission) && g.valid());
        if (!allowed)
            throw new AccessDeniedException(principal + " lacks permission: " + permission);
    }
}

